-- [DB GEÇMİŞİNDEN KURTARILDI 2026-07-11] Bu migration canlı veritabanına uygulanmıştı ancak repoda dosyası yoktu; supabase_migrations.schema_migrations.statements kolonundan geri çıkarıldı.

CREATE OR REPLACE FUNCTION public.admin_dashboard_stats() RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
  RETURN jsonb_build_object('total_users', (SELECT COUNT(*)::int FROM profiles), 'total_pitches', (SELECT COUNT(*)::int FROM pitches), 'total_matches', (SELECT COUNT(*)::int FROM matches), 'total_communities', (SELECT COUNT(*)::int FROM communities), 'pending_verifications', (SELECT COUNT(*)::int FROM profiles WHERE verification_status = 'pending'), 'pending_pitches', (SELECT COUNT(*)::int FROM pitches WHERE verification_status = 'pending'), 'pending_withdrawals', (SELECT COUNT(*)::int FROM owner_withdrawal_requests WHERE status = 'PENDING'), 'open_disputes', (SELECT COUNT(*)::int FROM match_disputes WHERE status IN ('OPEN','UNDER_REVIEW')), 'deletion_requests', (SELECT COUNT(*)::int FROM profiles WHERE account_deletion_requested_at IS NOT NULL), 'pending_community_requests', (SELECT COUNT(*)::int FROM community_creation_requests WHERE status = 'PENDING'), 'banned_users', (SELECT COUNT(*)::int FROM profiles WHERE is_banned = true), 'active_goalkeepers', (SELECT COUNT(*)::int FROM goalkeepers), 'active_referees', (SELECT COUNT(*)::int FROM referees), 'total_booking_revenue', COALESCE((SELECT SUM(amount) FROM booking_payments), 0), 'total_wallet_volume', COALESCE((SELECT SUM(ABS(amount)) FROM wallet_transactions), 0), 'active_promo_codes', (SELECT COUNT(*)::int FROM promo_codes WHERE is_active = true), 'commission_rate', (SELECT "commissionRate" FROM settings WHERE id = 1));
END; $$;
CREATE OR REPLACE FUNCTION public.admin_ops_queue() RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
  RETURN jsonb_build_object('pending_verifications', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'name', full_name, 'email', email, 'created_at', created_at)), '[]'::jsonb) FROM profiles WHERE verification_status = 'pending' LIMIT 20), 'pending_pitches', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'created_at', created_at)), '[]'::jsonb) FROM pitches WHERE verification_status = 'pending' LIMIT 20), 'pending_withdrawals', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'amount', amount, 'owner_id', owner_id, 'created_at', created_at)), '[]'::jsonb) FROM owner_withdrawal_requests WHERE status = 'PENDING' LIMIT 20), 'open_disputes', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'match_id', match_id, 'status', status, 'created_at', created_at)), '[]'::jsonb) FROM match_disputes WHERE status IN ('OPEN','UNDER_REVIEW') LIMIT 20), 'deletion_requests', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'name', full_name, 'email', email, 'requested_at', account_deletion_requested_at)), '[]'::jsonb) FROM profiles WHERE account_deletion_requested_at IS NOT NULL LIMIT 20), 'community_requests', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'requester_id', requester_id, 'created_at', created_at)), '[]'::jsonb) FROM community_creation_requests WHERE status = 'PENDING' LIMIT 20));
END; $$;
